# 확률 분포 예시: Python 3에서 실행 가능한 코드
dist = {"heads": 0.5, "tails": 0.5}
print(sum(dist.values()))

# 피처 스토어 예시: Python 3에서 실행 가능한 코드
feature_store = {"user_1": {"avg_order": 3.5}}
print(feature_store["user_1"]["avg_order"])

# 데이터 레이크 예시: Python 3에서 실행 가능한 코드
lake = {"logs": ["a", "b"], "images": ["img1"]}
print(lake.keys())

# 데이터 마트 예시: Python 3에서 실행 가능한 코드
warehouse = {"sales": [1, 2], "hr": [3]}
mart = {"sales": warehouse["sales"]}
print(mart)

# 데이터 카탈로그 예시: Python 3에서 실행 가능한 코드
catalog = {"orders": {"owner": "data-team", "columns": 12}}
print(catalog["orders"]["owner"])

# 데이터 거버넌스 예시: Python 3에서 실행 가능한 코드
policy = {"owner_required": True, "pii_restricted": True}
print(all(policy.values()))

# 시각화 원칙 예시: Python 3에서 실행 가능한 코드
chart = {"title": "Sales", "x_label": "Month", "y_label": "Revenue"}
print(all(chart.values()))
